package com.ebuddy.controller;
import com.ebuddy.service.*; import com.ebuddy.web.ApiModels; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/j2me") public class J2meController { final AuthService auth; final MessageService messages; public J2meController(AuthService a,MessageService m){auth=a;messages=m;} private UUID user(Authentication a){return (UUID)a.getPrincipal();}
 @PostMapping("/login") public ApiModels.J2meLogin login(@Valid @RequestBody ApiModels.LoginRequest r){var x=auth.login(new ApiModels.LoginRequest(r.username(),r.password(),"j2me",r.deviceLabel()));return new ApiModels.J2meLogin(x.token(),x.expiresAt());}
 @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public ApiModels.J2meLogin register(@Valid @RequestBody ApiModels.RegisterRequest r){return auth.register(r);}
 @PostMapping("/send") public ResponseEntity<String> send(Authentication a,@Valid @RequestBody ApiModels.SendRequest r){var m=messages.send(user(a),r);return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).body("OK "+m.id()+" "+m.status());}
 @GetMapping("/poll") public ApiModels.SyncView poll(Authentication a,@RequestParam(defaultValue="0")long cursor,@RequestParam(defaultValue="25")int wait,@RequestParam(defaultValue="20")int limit){long end=System.currentTimeMillis()+Math.min(Math.max(wait,0),25)*1000L;List<ApiModels.MessageView> result;do{result=messages.sync(user(a),cursor,limit);if(!result.isEmpty()||wait<=0||System.currentTimeMillis()>=end)break;try{Thread.sleep(Math.min(1000,Math.max(1,end-System.currentTimeMillis())));}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}while(true);String next=result.isEmpty()?Long.toString(cursor):Long.toString(result.get(result.size()-1).sequence());return new ApiModels.SyncView(result,next,result.size()>=Math.min(limit,20));}
}
